        pedido.setNombreCompleto(nombreCompleto);
        pedido.setDireccion(direccion);
        pedido.setProvincia(provincia);
        pedido.setTitularTarjeta(titularTarjeta);
        pedido.setCardNumber(cardNumber);
        pedido.setTipoTarjeta(tipoTarjeta);
        pedido.setRegalo(regalo);
        pedido.setObservaciones(observaciones);
        pedido.setItems(items);
        return pedido;
    }

    public ResumenPedido obtenerPedido(int pedidoId) {
        // Simulate DB fetch
        return new ResumenPedido();
    }

    public void actualizarEstadoPedido(int pedidoId, String estado) {
        System.out.println("Pedido " + pedidoId + " updated to status: " + estado);
    }
}

