package tienda.discos.servicioJPAImpl;

import java.util.List;
import java.util.Map;
import javax.persistence.EntityManager;
import javax.persistence.PersistenceContext;
import javax.persistence.Query;
import org.hibernate.query.internal.NativeQueryImpl;
import org.hibernate.transform.AliasToEntityMapResultTransformer;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tienda.discos.constantesSQL.ConstantesSQL;
import tienda.discos.model.Carrito;
import tienda.discos.model.Disco;
import tienda.discos.model.ProductoCarrito;
import tienda.discos.model.Usuario;
import tienda.discos.servicios.ServicioCarrito;

@Service
@Transactional
public class ServicioCarritoImpl implements ServicioCarrito {

    @PersistenceContext
    private EntityManager entityManager;

    @Override
    public void agreggarProducto(int idUsuario, int idProducto, int quantity) {
        Usuario uBaseDatos = entityManager.find(Usuario.class, idUsuario);
        Carrito c = uBaseDatos.getCarrito();
        if (c == null) {
            c = new Carrito();
            c.setUsuario(uBaseDatos);
            uBaseDatos.setCarrito(c);
            entityManager.persist(c);
        }
        boolean productFound = false;
        for (ProductoCarrito pc : c.getProductosCarrito()) {
            if (pc.getDisco().getId() == idProducto) {
                productFound = true;
                pc.setCantidad(pc.getCantidad() + quantity);
                entityManager.merge(pc);
            }
        }
        if (!productFound) {
            ProductoCarrito pc = new ProductoCarrito();
            pc.setCarrito(c);
            pc.setDisco(entityManager.find(Disco.class, idProducto));
            pc.setCantidad(quantity);
            entityManager.persist(pc);
        }
    }

    @Override
    public void actualizarProductoCarrito(int idUsuario, int idProducto, int quantity) {
        // TODO
    }

    @Override
    public void borrarProductoCarrito(int idUsuario, int idProducto) {
        Usuario u = entityManager.find(Usuario.class, idUsuario);
        Carrito c = u.getCarrito();
        if (c != null) {
            Query query = entityManager.createNativeQuery(ConstantesSQL.SQL_BORRAR_PRODUCTO_CARRITO);
            query.setParameter("carrito_id", c.getId());
            query.setParameter("id_disco", idProducto);
            query.executeUpdate();
        }
    }

    @Override
    public List<Map<String, Object>> obtenerProductosCarrito(int idUsuario) {
        Usuario u = entityManager.find(Usuario.class, idUsuario);
        Carrito c = u.getCarrito();
        List<Map<String, Object>> res = null;
        if (c != null ) {
            Query query = entityManager.createNativeQuery(ConstantesSQL.SQL_OBTENER_PRODUCTOS_CARRITO);
            query.setParameter("par_variable", c.getId());
            NativeQueryImpl<?> nativeQuery = (NativeQueryImpl<?>) query;
            nativeQuery.setResultTransformer(AliasToEntityMapResultTransformer.INSTANCE);
            res = (List<Map<String, Object>>) nativeQuery.getResultList();
        }
        return res;
    }
}

package tienda.discos.servicioJPAImpl;

import java.util.List;
import java.util.Map;
import javax.persistence.EntityManager;
import javax.persistence.PersistenceContext;
import javax.persistence.Query;
import org.hibernate.query.internal.NativeQueryImpl;
import org.hibernate.transform.AliasToEntityMapResultTransformer;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tienda.discos.constantesSQL.ConstantesSQL;
import tienda.discos.model.Usuario;
import tienda.discos.servicios.ServicioUsuarios;

@Service
@Transactional
public class ServicioUsuariosImpl implements ServicioUsuarios {

    @PersistenceContext
    private EntityManager entityManager;

    @Override
    public void registarUsuario(Usuario u) {
        entityManager.persist(u);
    }

    @Override
    public Usuario obtenerUserPorMailYpass(String email, String pass) {
        Query query = entityManager.createQuery("select u from Usuario u where u.email = :email and u.pass = :pass");
        query.setParameter("email", email);
        query.setParameter("pass", pass);

        List<Usuario> resultado = query.getResultList();
        if (resultado.isEmpty()) {
            return null;
        } else {
            return resultado.get(0);
        }
    }

    @Override
    public Usuario obtenerUserPorId(int id) {
        return (Usuario) entityManager.createQuery("select u from Usuario u where u.id = :user_id")
                .setParameter("user_id", id)
                .getResultList().get(0);
    }

    @Override
    public Map<String, Object> nativeObtenerUserPorId(int id) {
        Query query = entityManager.createNativeQuery(ConstantesSQL.SQL_OBTENER_USUARIO_POR_ID);
        query.setParameter("user_id", id);
        NativeQueryImpl<?> nativequery = (NativeQueryImpl<?>) query;
        nativequery.setResultTransformer(AliasToEntityMapResultTransformer.INSTANCE);
        List<Map<String, Object>> test = (List<Map<String, Object>>) nativequery.getResultList();
        return test.isEmpty() ? null : test.get(0);
    }

    @Override
    public List<Usuario> obtenerUsuarios() {
        return entityManager.createQuery("select u from Usuario u").getResultList();
    }

    @Override
    public void actualizarDatos(Integer id, String nombreUsuario, String pass, String telefono, String pais) {
        Usuario u = entityManager.find(Usuario.class, id);
        u.setNombre(nombreUsuario);
        u.setPass(pass);
        u.setTel(telefono);
        u.setPais(pais);
        entityManager.merge(u);
    }

    @Override
    public void guardarCambiosUsuario(Usuario usuarioEditar) {
        entityManager.merge(usuarioEditar);
    }
}

